// Turns n8n's error report into what the portal's Needs attention list expects.
const e = $json;
const ex = e.execution || {};
const err = ex.error || {};
const wf = e.workflow || {};
return [{ json: {
  workflow_name: wf.name || 'unknown workflow',
  workflow_id: wf.id || null,
  execution_id: ex.id || null,
  execution_url: ex.url || null,
  node: err.node?.name || ex.lastNodeExecuted || null,
  message: String(err.message || err.description || 'The workflow stopped with an error').slice(0, 1500),
}}];
